    f += 0.1250  * noiseNice(p); p = m2*p*1.75;
    f += 0.0625  * noiseNice(p); p = m2*p*1.5;

    // f += 0.03125 * noiseNice(p); p = m2*p*2.04;
    // f += 0.015625* noiseNice(p);

